const floors = 3, height = 3.2, width = 12, depth = 8, t = 0.25;
const doc = await xeo.document.create({
  project: { name: 'Script building' },
  scaffold: { storeys: Array.from({ length: floors }, (_, i) => ({ name: 'Level ' + (i + 1), elevation: i * height })) },
});
const corners = [[0, 0], [width, 0], [width, depth], [0, depth]];
for (const storey of doc.storeys) {
  await xeo.element.add({ type: 'IfcSlab', name: 'Floor', container: storey, location: [0, 0, -0.3],
    geometry: { kind: 'slab', outline: corners, thickness: 0.3 }, color: [0.7, 0.7, 0.7] });
  for (let i = 0; i < 4; i++) {
    const wall = await xeo.element.add({ type: 'IfcWall', name: 'Perimeter wall ' + (i + 1), container: storey,
      geometry: { kind: 'wall', start: corners[i], end: corners[(i + 1) % 4], height, thickness: t },
      color: [0.85, 0.82, 0.75], psets: { Pset_WallCommon: { IsExternal: true } } });
    await xeo.opening.add({ host: wall.ref, offset: 2, sill: 0.9, width: 1.6, height: 1.4, fill: { type: 'IfcWindow' } });
  }
  for (const x of [4, 8]) {
    await xeo.element.add({ type: 'IfcColumn', container: storey, location: [x, depth / 2, 0],
      geometry: { kind: 'column', profile: { kind: 'rectangle', width: 0.4, depth: 0.4 }, height } });
  }
}
console.log(floors + ' storeys created');
`],["Add wall + door",`// Adds a wall with a door to the highest storey of the loaded model (where it is easy to see).
const storeys = await xeo.query('is IfcBuildingStorey', { select: ['ref', 'name', 'Elevation'] });
storeys.sort((a, b) => (b.Elevation ?? 0) - (a.Elevation ?? 0));
const storey = storeys[0];
console.log('storey:', storey.name);
const wall = await xeo.element.add({ type: 'IfcWall', name: 'Script wall', container: storey.ref,
  geometry: { kind: 'wall', start: [0, 0], end: [5, 0], height: 2.8, thickness: 0.2 }, color: [0.9, 0.6, 0.3] });
await xeo.opening.add({ host: wall.ref, offset: 1.5, width: 0.9, height: 2.1, fill: { type: 'IfcDoor', name: 'Script door' } });
console.log('wall at', wall.worldLocation);
`],["Quantity take-off",`// Wall count per storey. Nothing is changed, so there is nothing to apply.
const rows = await xeo.query('is IfcWall', { select: ['ref', 'storey.Name', 'Qto_WallBaseQuantities.NetSideArea', 'BaseQuantities.NetSideArea'] });
const perStorey = {};
for (const row of rows) {
  const key = row['storey.Name'] ?? '(none)';
  const area = Number(row['Qto_WallBaseQuantities.NetSideArea'] ?? row['BaseQuantities.NetSideArea'] ?? 0);
  perStorey[key] ??= { walls: 0, area: 0 };
  perStorey[key].walls += 1;
  perStorey[key].area += area;
}
for (const [storey, q] of Object.entries(perStorey)) console.log(storey + ': ' + q.walls + ' walls, ' + q.area.toFixed(1) + ' m2');
return perStorey;
`],["Data quality audit",`// Elements without a name are coloured red in the view.
