const unnamed = rows.filter((row) => !row.name);
console.log(rows.length + ' elements, ' + unnamed.length + ' without a name');
await xeo.viewer.clearColors();
if (unnamed.length > 0) await xeo.viewer.color({ refs: unnamed.map((row) => row.ref), color: 'red' });
return { elements: rows.length, unnamed: unnamed.length };
